			title = "森林传说",
			text = [=[• {link:darkshire}夜色镇{/link}的孩子们听着一个故事长大：一位名叫{link:abercrombie}防腐师{/link}的善良炼{link:ginro-hearthkindle}金{/link}术士，因亡妻之痛而发了疯。
• 在镇上，{link:stalvan-mistmantle}斯塔文·密斯特曼托{/link}这个名字只能低声说出。
• 在黑暗林中迷路的人有时说，是一道影子把他们领回了大路。]=],
		},
		{ title = "未载", text = "关于这些日子的编年史都没有记载最初使暮色森林陷入黑暗的是什么，也没有记载那发生在哪一年。" },
	},
})

Translate("zhCN", "darkshire", {
	title = "夜色镇",
	sections = {
		{
			title = "概述",
			text = [=[夜色镇是{link:duskwood}暮色森林{/link}最后一座真正的城镇，一簇木屋围绕着森林东部的一座广场。{link:the-night-watch}守夜人{/link}把守着它的大门。镇长{link:lord-ello-ebonlocke}艾尔罗·埃伯洛克公爵{/link}带着他的{link:shadow-council}议会{/link}和书记员在镇议会厅主事。旅人在猩红渡鸦旅店饮酒，那里的厨师供应来历可疑的蛋糕。一位占卜师在广场边的屋子里翻看纸牌，一位历史学家守着一座一年比一年空的图书馆。这里的人们整夜不熄灯火。]=],
		},
	},
})

Translate("zhCN", "raven-hill", {
	title = "乌鸦岭",
	sections = {
		{
			title = "概述",
			text = [=[乌鸦岭曾是{link:duskwood}暮色森林{/link}西部一座自豪的村庄。如今它是一座鬼镇。房屋空无一人，村民长眠于北方的大墓地中。村庄陷落后，关于它的记录所剩无几，连{link:darkshire}夜色镇{/link}的历史学家也说不出多少。近来镇民听说有影子在屋舍之间移动，一扇窗里亮着灯。那所谓的闹鬼不过是一个躲藏起来的受惊男子。曾经守卫这座村庄的{link:the-valor-family}瓦洛尔家族{/link}的鬼魂，则是另一回事了。]=],
		},
	},
})

Translate("zhCN", "raven-hill-cemetery", {
	title = "乌鸦岭墓地",
	sections = {
		{
			title = "概述",
			text = [=[乌鸦岭墓地铺展在{link:duskwood}暮色森林{/link}的西北，广阔得如今已主宰了周围的土地。墓中的骷髅在墓碑间列队行进，食尸鬼盘踞在陵墓里。{link:the-night-watch}守夜人{/link}一次又一次派志愿者前来，亡者却总是卷土重来。骑士{link:mor-ladim}摩根·拉迪莫尔{/link}正是在这里找到了家人的坟墓，后来他自己的坟墓也在这里被发现空空如也。墓地北缘的一间小屋里住着一位年老的隐士。他的门边有一座属于名叫{link:eliza}伊莉莎{/link}的女子的坟墓。]=],
		},
	},
})

Translate("zhCN", "forlorn-rowe", {
	title = "荒弃鬼屋",
	sections = {
		{
			title = "概述",
			text = [=[荒弃鬼屋是{link:raven-hill-cemetery}乌鸦岭墓地{/link}上方一座山丘上的房子。它是死灵法师{link:morbent-fel}摩本特·费尔{/link}的巢穴，{link:deadwind-pass}逆风小径{/link}的{link:dark-riders}黑暗骑士{/link}便是来这里与他交谈。守卫山丘的骷髅是他的仆从。他曾一度从盗墓者{link:dextren-ward}迪克斯特·瓦德{/link}手中购买尸体，直到瓦德被抓获并被送进{link:stormwind-city}暴风城{/link}的{link:the-stockade}监狱{/link}。{link:sven-yorgen}斯温·约根{/link}在西边的营地监视着这座房子，等待它归于沉寂的那一天。]=],
		},
	},
})

Translate("zhCN", "manor-mistmantle", {
	title = "密斯特曼托庄园",
	sections = {
		{
			title = "概述",
			text = [=[密斯特曼托庄园位于{link:darkshire}夜色镇{/link}以北不远处，是黑色树木下一座孤零零的房子。它的主人是{link:stalvan-mistmantle}斯塔文·密斯特曼托{/link}，他曾是孩子们的老师，如今他的名字却成了谋杀的代名词。他来自遥远北方的{link:silverpine-forest}银松森林{/link}，曾在信末署上故乡的名字。{link:the-night-watch}守夜人{/link}长久以来怀疑他犯下了旧日的命案，却什么也证明不了。镇民远远绕开这座房子，夜里经过的人也不会多作停留。]=],
		},
	},
})

Translate("zhCN", "roland-s-doom", {
	title = "罗兰之墓",
	sections = {
		{
			title = "概述",
			text = [=[罗兰之墓是{link:duskwood}暮色森林{/link}南部的一座矿洞。它的坑道一向难以开采，却并不致命，直到一名矿工从一堆碎石中拔出了一把奇怪镰刀的长柄。当夜，狼人从岩石中涌了出来。半数矿工在最初的片刻里丧命。{link:nightbane-worgen}夜行{/link}至今仍占据着这座矿洞，远远就能望见他们的篝火。暮色森林最早的狼人就是在这里被发现的，{red:scythe-of-elune}艾露恩之镰{/red}的踪迹也在这里断绝。]=],
		},
	},
})

Translate("zhCN", "addle-s-stead", {
	title = "腐草农场",
	sections = {
		{
			title = "概述",
			text = [=[腐草农场是{link:duskwood}暮色森林{/link}西南一座废弃的农场，位于从{link:westfall}西部荒野{/link}而来的大路以南。农夫们已经离去。{link:defias-brotherhood}迪菲亚潜行者{/link}把这里变成了聚会之所，他们的夜刃和附魔师在荒废的田地间放哨。前些时候，{link:the-night-watch}守夜人{/link}看到一群迪菲亚特工聚集在那里，人数之多，表明有重要的东西经过了此地。据说一位{link:raven-hill}乌鸦岭{/link}卫兵的鬼魂至今仍在田间徘徊。]=],
		},
	},
})

Translate("zhCN", "the-rotting-orchard", {
	title = "烂果园",
	sections = {
		{
			title = "概述",
			text = [=[烂果园位于{link:darkshire}夜色镇{/link}西南。果树仍成排而立，果实却早已落地腐烂。{link:nightbane-worgen}夜行狼人{/link}占领了这里。他们的暗影编织者和黑暗奔行者在树干间狩猎，{link:carevin-family}卡雷文家族{/link}的猎人便是把想要加入他们的人派到这里来。他们的猎人{link:calor}卡洛尔{/link}已经得知，黑暗奔行者是夜行的主力，每杀死一个，很快就有另一个取而代之。]=],
		},
	},
})

Translate("zhCN", "the-yorgen-farmstead", {
	title = "约根农场",
	aliases = { "斯温的农场" },
	sections = {
		{
			title = "概述",
			text = [=[约根农场位于{link:duskwood}暮色森林{/link}南部。它曾是{link:sven-yorgen}斯温·约根{/link}一家的家园，直到{link:deadwind-pass}逆风小径{/link}的{link:dark-riders}黑暗骑士{/link}趁斯温外出时到来，屠杀了屋里的所有人。斯温回来时，看见一个阴影般的身影在谷仓附近一截老树桩后面掩埋着什么。那个坑里埋的是一本日记。日记讲述了一名从{link:roland-s-doom}罗兰之墓{/link}逃出来、躲进约根家谷仓的矿工，他目睹了这一家人的死亡。]=],
		},
	},
})

Translate("zhCN", "vul-gol-ogre-mound", {
	title = "沃古尔食人魔山",
	aliases = { "沃古尔" },
	sections = {
		{
			title = "概述",
			text = [=[沃古尔食人魔山是{link:duskwood}暮色森林{/link}南部的一片洞穴，由裂拳氏族的{link:ogres}食人魔{/link}占据。他们的战士、火焰编织者和监工劫掠道路，把路上找到的东西统统带走，连一位老隐士装着草药和工具的箱子也不放过。食人魔扎克沃尔住在山中。他戴着一只巨大的单片眼镜，{link:darkshire}夜色镇{/link}的一位学者为了自己的目的对它垂涎已久。人们认为，古时{link:raven-hill}乌鸦岭{/link}一位{link:the-night-watch}守望者{/link}的鬼魂仍在土丘附近的路上游荡，依旧在与食人魔作战。]=],
		},
	},
})

Translate("zhCN", "brightwood-grove", {
	title = "阳光树林",
	sections = {
		{
			title = "概述",
			text = [=[阳光树林是{link:duskwood}暮色森林{/link}中的一片{link:moonglade}林地{/link}。不论当初赋予它这个名字的是怎样的光亮，如今都已不复存在。{link:nightbane-worgen}夜行狼人{/link}在那里狩猎，他们的暗影编织者成群穿行于林间，{link:darkshire}夜色镇{/link}的猎人提起这片树林的名字时总是苦笑。与{link:the-rotting-orchard}烂果园{/link}一样，这里也是{link:carevin-family}卡雷文家族{/link}的试炼之地。想要加入卡雷文家族之战的人，必须先从它的阴影中活着回来。]=],
		},
	},
})

Translate("zhCN", "twilight-grove", {
	title = "黎明森林",
	sections = {
		{
			title = "概述",
			text = [=[黎明森林位于{link:duskwood}暮色森林{/link}的中心，在横穿森林的大路以北。那里耸立着一棵巨树。这是{link:eastern-kingdoms}东部王国{/link}少数几处现世与{link:emerald-dream}翡翠梦境{/link}相接的地方之一，翡翠梦境是绿龙守护的国度。这样的门户在世上十分罕见，其余几处都在遥远的地方，在{link:the-hinterlands}辛特兰{/link}和{link:kalimdor}卡利姆多{/link}。{link:darkshire}夜色镇{/link}的居民无人谈起这片树林，也无人声称知道为何这样一个地方会坐落在亡者的森林之中。]=],
		},
	},
})

Translate("zhCN", "tranquil-gardens-cemetery", {
	title = "静谧花园墓场",
	aliases = { "静谧花园" },
	sections = {
		{
			title = "概述",
			text = [=[静谧花园墓场位于{link:darkshire}夜色镇{/link}以南，{link:duskwood}暮色森林{/link}的东南部。如今它的名字成了残酷的玩笑。骷髅战士和骷髅法师在坟墓间游荡，一只疯狂的食尸鬼带着一面偷来的镜子在小径上徘徊。它是森林中离小镇最近的墓地。这里的骷髅头颅中长着腐烂之花，夜色镇的旅店老板用这种花酿出一种{link:brewnall-village}烈酒{/link}，据说烈得足以让死人复活。每当亡者在那里起身，{link:the-night-watch}守夜人{/link}总是最先得到消息。]=],
		},
	},
})

Translate("zhCN", "the-hushed-bank", {
	title = "寂静河岸",
	sections = {
		{
			title = "概述",
			text = [=[寂静河岸沿着{link:duskwood}暮色森林{/link}最西缘的河流延伸。{link:sven-yorgen}斯温·约根{/link}与他的同伴拉尔斯以及几名忠诚的追随者在这里扎营。他们人数太少，抽不出人手去取补给，于是{link:darkshire}夜色镇{/link}的{link:carevin-family}卡雷文家族{/link}尽其所能给他们送去物资。他们靠打猎为生，饥饿的恐狼从林中下来，为每一块肉与他们争斗。斯温从这片孤寂的河岸眺望东方，死灵法师{link:morbent-fel}摩本特·费尔{/link}就在那里的山丘上等待。]=],
		},
	},
})

Translate("zhCN", "the-darkened-bank", {
	title = "暗色河滩",
	sections = {
		{
			title = "概述",
			text = [=[暗色河滩是{link:duskwood}暮色森林{/link}漫长的北缘，河流在森林与{link:elwynn-forest}艾尔文{/link}的山麓之间流过。毒网蜘蛛沿岸筑巢，猩红渡鸦旅店的厨师看重它们的腿，用来做他的蛋糕。{link:the-night-watch}守望者{/link}在附近的北路巡逻，其中一人守着镇外的那一段路。在那条路上，一名地精商人在一位孤单的守望者身旁摆了个摊子，把稀罕的货物卖给任何敢于走这一趟的人。]=],
		},
	},
})

Translate("zhCN", "beggar-s-haunt", {
	title = "乞丐鬼屋",
	sections = {
		{
			title = "概述",
