	sections = {
		{
			title = "概述",
			text = [=[摩根·拉迪莫尔是一位为无辜者和穷人而战的骑士。他十八岁时娶了一个名叫莉丝的姑娘，他们育有一子二女。当战火燃到{link:lordaeron}洛丹伦{/link}时，他北上与{link:uther-the-lightbringer}光明使者乌瑟尔{/link}并肩作战。回到家乡时，他发现森林已经腐朽，家宅成了废墟。如今他以摩拉迪姆之名在墓地中游荡，成了一个无故杀戮的亡者。]=],
		},
		{
			title = "意义",
			text = [=[{link:morgan-stern}摩根{/link}的堕落是{link:duskwood}暮色森林{/link}最悲伤的故事。他是一个被悲痛击垮的好人。他的名字是一个警示：森林的黑暗即使对最坚强的心也能做出什么。]=],
		},
		{
			title = "事迹",
			text = [=[• 他在北方的战争中追随{link:uther-the-lightbringer}乌瑟尔{/link}，目睹了圣骑士团的解散、乌瑟尔的死以及瘟疫的蔓延。
• 他搜遍了{link:duskwood}暮色森林{/link}的每一座农场和房屋，寻找他的家人。
• 他在{link:raven-hill-cemetery}乌鸦岭墓地{/link}发现了一块刻着妻子名字的墓碑。
• 悲痛之中，他杀死了墓地的三名看守，随后结束了自己的生命。]=],
		},
	},
	chapters = {
		{
			title = "风化的坟墓",
			hint = "在乌鸦岭墓地的远端寻找一座坟墓。",
			text = [=[他被草草埋葬在墓地边缘之外，没有举行任何仪式。几天后，泥土被翻动过，坟墓空了。{link:darkshire}夜色镇{/link}的历史学家在战前就认识{link:morgan-stern}摩根{/link}，他保存着一本讲述摩根故事的书。]=],
		},
		{
			title = "女儿的戒指",
			hint = "为摩根·拉迪莫尔的坟墓带去慰藉。",
			text = [=[{link:morgan-stern}摩根{/link}死时以为全家都已死去。但他的一个女儿莎拉活了下来。当她的戒指被放在他的坟上时，一个声音随风而起。骑士惊奇地说出了女儿的名字，压在他灵魂上的重担被卸下了。他把自己的剑{link:arko-narin}阿尔科{/link}斯交给了为他带来安宁的人，他最后的话语是留给妻子莉丝的。]=],
		},
