Translate("zhCN", "the-night-watch", {
	title = "守夜人",
	aliases = { "守望者" },
	sections = {
		{
			title = "概述",
			text = [=[守夜人是{link:darkshire}夜色镇{/link}的民兵。当一种邪恶的魔法渗入{link:duskwood}暮色森林{/link}、{link:stormwind-city}暴风城{/link}召回其卫兵时，它应运而生。从那以后，守夜人便是小镇与森林之间唯一的屏障。它由{link:commander-althea-ebonlocke}指挥官阿尔泰娅·埃伯洛克{/link}率领，其成员被称为守望者。]=],
		},
		{
			title = "守望者",
			text = [=[守望者把守着{link:darkshire}夜色镇{/link}的大门和广场，还有几人驻守在道路上孤零零的哨岗：西路上两人，北路上一人，身旁是一名地精商人。他们人数太少，他们自己也知道。指挥官无法把他们派到离镇太远的地方。当亡者在墓地中起身时，她只能请陌生人代他们前往。亡灵骑士{link:mor-ladim}摩拉迪姆{/link}已经杀死了她最强的几名守望者。]=],
		},
		{
			title = "守夜人与世界",
			text = [=[{link:darkshire}夜色镇{/link}已经把守夜人当作唯一的军队来依靠。当{link:lakeshire}湖畔镇{/link}的法官{link:magistrate-solomon}所罗门{/link}恳求埃伯{link:locke-okarr}洛克{/link}勋爵派出守夜人时，镇长拒绝了：如果守夜人开拔，小镇会在它走到森林边缘之前就陷落。并非所有人都钦佩它。猎人{link:calor}卡洛尔{/link}离开守夜人投奔了{link:carevin-family}卡雷文家族{/link}，称其自满。守望者中有阵亡骑士的女儿{link:sarah-ladimore}莎拉·拉迪莫尔{/link}，在{link:raven-hill}乌鸦岭{/link}的传说中，还有弓箭手梅里克·瓦{link:overlord-ror}洛尔{/link}。]=],
		},
	},
})

Translate("zhCN", "nightbane-worgen", {
	title = "夜行狼人",
	aliases = { "夜行" },
	sections = {
		{
			title = "概述",
			text = [=[夜行是{link:duskwood}暮色森林{/link}的{red:worgen}狼人{/red}：成群猎杀于森林南半部的巨大狼人。暗影编织者和黑暗奔行者在{link:brightwood-grove}阳光树林{/link}和{link:the-rotting-orchard}烂果园{/link}中游荡。他们中最强大的——邪牙和腐化者——把篝火燃在南方的洞穴附近以及{link:roland-s-doom}罗兰之墓{/link}的矿洞中。]=],
		},
		{
			title = "他们的到来",
			text = [=[狼人并非一直在这里。{link:darkshire}夜色镇{/link}的猎人说，他们仿佛是凭空出现的，最早的一批是在{link:roland-s-doom}罗兰之墓{/link}被发现的。那座矿洞的一名矿工，那个被称为{link:jitters}基特斯{/link}的人，讲述了事情的经过。他在一堆碎石中发现了一把镰刀的长柄，把它拔了出来。当夜，狼人从坑道的每一个洞口和岩架中涌出，大多数矿工都死了。他在逃跑中丢失了镰刀。他不知道把狼人带到{link:duskwood}暮色森林{/link}的是不是自己，但他害怕是。

那把镰刀就是{red:scythe-of-elune}艾露恩之镰{/red}。一位名叫{link:sentinel-velene-starstrike}维琳{/link}德·星歌的{link:night-elves}暗夜精灵{/link}女祭司把它带进了这片树林，她的命运是在矿洞中得知的。{link:darnassus}达纳苏斯{/link}的{link:sentinels}哨兵{/link}深感不安：她们女神的礼物竟然离开了她的仆从之手。]=],
		},
		{
			title = "对他们的战争",
			text = [=[{link:carevin-family}卡雷文家族{/link}和他们的猎人{link:calor}卡洛尔{/link}与夜行进行着一场无休止的战争。他们每消灭一群，很快就有另一群取而代之。{link:darkshire}夜色镇{/link}还没有人知道是什么力量在吸引着他们。]=],
		},
		{
			title = "未载",
			text = [=[关于这些日子的编年史都没有解释镰刀是如何召来狼人的，也没有说明夜行是否与{link:silverpine-forest}银松森林{/link}的狼人同源。]=],
		},
	},
})

Translate("zhCN", "the-valor-family", {
	title = "瓦洛尔家族",
	sections = {
		{
			title = "概述",
			text = [=[瓦洛尔家族是{link:raven-hill}乌鸦岭{/link}陷落前的守护者。在荒废的村庄中找到的一本典籍《英勇的回忆》逐一记录了他们。它的作者为他们哀悼，并为他们的离去而自责。]=],
		},
		{
			title = "家族成员",
			text = [=[• {b}格兰特·瓦{link:overlord-ror}洛尔{/link}领主。{/b} 家族之长，{link:raven-hill}乌鸦岭{/link}的领袖。黑暗进入树林时，他第一个召集了村民。他最憎恨的敌人是亡灵，亲自在墓地中巡逻。亡灵给他留下的一道重伤始终没有真正痊愈。
• {b}卡珊德拉·瓦洛尔夫人。{/b} 他的妻子。关于她，人们只知道她对家人的爱。
• {b}希尔维娅·瓦洛尔。{/b} 乌鸦岭的一名卫兵，以将强盗和骗子斩于剑下而闻名。据说她从未抛弃{link:duskwood}暮色森林{/link}的农场。
• {b}艾拉·瓦洛尔。{/b} 父亲病倒后，她到森林中采集食物，后来她宁愿待在黑暗的树林里，也不愿待在村中。迷路的旅人说起一道把他们领回大路的影子。
• {b}梅里克·瓦洛尔。{/b} 最小的儿子。他加入了{link:the-night-watch}守夜人{/link}，用他的弓守护着道路。]=],
		},
		{
			title = "他们的鬼魂",
			text = [=[瓦{link:overlord-ror}洛尔{/link}一家同时消失了。如今他们的灵魂在森林中游荡，仍在做着生前所做的事：格兰特在墓地的骷髅之间，希尔维娅在农场附近，艾拉在树林里，梅里克在道路上。{link:darkshire}夜色镇{/link}的历史学家{link:sirra-von-indi}希拉·沃宁迪{/link}相信，是某种共同的悲伤把他们束缚在这个世界上。]=],
		},
		{ title = "未载", text = "瓦洛尔家族遭遇了什么，又是什么束缚着他们的灵魂，至今仍不得而知。" },
	},
})

Translate("zhCN", "carevin-family", {
