			text = [=[卡雷文家族是{link:darkshire}夜色镇{/link}的一户人家，他们发起了一场私人战争。他们猎杀恶魔、亡灵以及所有援助它们的人，不信任任何不愿帮助他们事业的人。他们的家主是{link:jonathan-carevin}乔纳森·卡尔文{/link}。他的猎人{link:calor}卡洛尔{/link}曾是{link:the-night-watch}守夜人{/link}的一员，领导着对{link:nightbane-worgen}夜行狼人{/link}的战斗。]=],
		},
		{
			title = "家族成员",
			text = [=[艾莱尼·卡尔文照看着镇上那些被遗弃之人的需要。她给西边的{link:sven-yorgen}斯温·约根{/link}送去补给，称他是在做{link:holy-light}圣光{/link}之事的人，她还担心那位不再来赶集的老隐士。斯考特·卡尔文在广场上卖蘑菇，一个名叫本杰明的小男孩在宅子附近玩耍。]=],
		},
		{
			title = "卡雷文家族与守夜人",
			text = [=[卡雷文家族并不公开反对{link:the-night-watch}守夜人{/link}。然而{link:calor}卡洛尔{/link}毫不掩饰他对守夜人的蔑视。他梦想着有一天，卡雷文家族的追随者人数会超过守望者。]=],
		},
	},
})
